  class Atom { public string E; public double X,Y,Z; public Atom(string e,double x,double y,double z){E=e;X=x;Y=y;Z=z;} }
  class ResultData {
    public string FileName="", Kind="", Text="", Method="", Basis="";
    public List<Atom> Atoms=new List<Atom>(); public List<double> Energies=new List<double>(); public List<double> Frequencies=new List<double>();
    public List<string> Warnings=new List<string>(), Errors=new List<string>(); public int? Charge=null, Multiplicity=null; public bool Converged=false; public double? Energy=null; public int Cycles=0;
  }
  static class Program { [STAThread] static void Main(string[] args) { Application.EnableVisualStyles(); Application.SetCompatibleTextRenderingDefault(false); MainForm f=new MainForm(); if(args.Length>0) f.Shown+=(s,e)=>f.OpenPath(args[0]); Application.Run(f); } }

