      Button inp=MakeButton("打开输入 .inp"),outb=MakeButton("打开输出 .out"),geom=MakeButton("打开结构"),save=MakeButton("导出 XYZ"); buttons.Controls.AddRange(new Control[]{inp,outb,geom,save}); inp.Click+=(s,e)=>Choose("ORCA 输入 (*.inp)|*.inp|所有文件 (*.*)|*.*"); outb.Click+=(s,e)=>Choose("ORCA 输出 (*.out;*.log)|*.out;*.log|所有文件 (*.*)|*.*"); geom.Click+=(s,e)=>Choose("结构文件 (*.xyz;*.cif)|*.xyz;*.cif|Gaussian 输入 (*.gjf;*.com)|*.gjf;*.com|所有文件 (*.*)|*.*"); save.Click+=(s,e)=>SaveXYZ();
      SplitContainer split=new SplitContainer(){Dock=DockStyle.Fill,BackColor=bg,Padding=new Padding(10)}; root.Controls.Add(split,0,1); Shown+=(s,e)=>{if(split.Width>900){split.Panel1MinSize=400;split.Panel2MinSize=380;split.SplitterDistance=Math.Min(700,split.Width-380);}};
