      Button bond=MakeButton("键"),label=MakeButton("元素"),fit=MakeButton("适配"); bond.Width=52;label.Width=62;fit.Width=62;viewBtns.Controls.AddRange(new Control[]{bond,label,fit});
      molecule=new MoleculeCanvas(){Dock=DockStyle.Fill,BackColor=Color.FromArgb(20,22,29)}; left.Controls.Add(molecule); molecule.BringToFront(); bond.Click+=(s,e)=>{molecule.ShowBonds=!molecule.ShowBonds;bond.BackColor=molecule.ShowBonds?Color.FromArgb(78,68,150):panel2;molecule.Invalidate();}; label.Click+=(s,e)=>{molecule.ShowLabels=!molecule.ShowLabels;label.BackColor=molecule.ShowLabels?Color.FromArgb(78,68,150):panel2;molecule.Invalidate();}; fit.Click+=(s,e)=>molecule.ResetView();
      molecule.DragEnter+=OnDragEnter; molecule.DragDrop+=OnDragDrop;
      countLabel=new Label(){Text="",AutoSize=true,BackColor=Color.FromArgb(35,38,48),ForeColor=Color.FromArgb(190,197,210),Padding=new Padding(8,5,8,5),Location=new Point(12,52)}; molecule.Controls.Add(countLabel); countLabel.BringToFront();
