      TabPage summary=Page("概览"),atoms=Page("原子"),freq=Page("频率"),log=Page("输入 / 日志"); tabs.TabPages.AddRange(new TabPage[]{summary,atoms,freq,log});
      FlowLayoutPanel cards=new FlowLayoutPanel(){Dock=DockStyle.Top,Height=174,Padding=new Padding(10),BackColor=panel,AutoScroll=true}; summary.Controls.Add(cards);
      Label nat,charge,method,energy,cycles,conv; AddCard(cards,"原子数",out nat); AddCard(cards,"电荷 / 多重度",out charge); AddCard(cards,"方法 / 基组",out method); AddCard(cards,"最终能量 (Eh)",out energy); AddCard(cards,"优化循环",out cycles); AddCard(cards,"优化状态",out conv);
