    Action voidUpdate;
    TabPage Page(string name){TabPage p=new TabPage(name);p.BackColor=panel;p.ForeColor=text;return p;}
    ListView NewList(string[] cols){ListView v=new ListView(){Dock=DockStyle.Fill,View=View.Details,FullRowSelect=true,GridLines=true,BackColor=Color.FromArgb(20,22,29),ForeColor=text,BorderStyle=BorderStyle.None};foreach(string c in cols)v.Columns.Add(c, c=="#"?55:110);return v;}
    void AddCard(Control parent,string caption,out Label value){Panel p=new Panel(){Width=195,Height=67,BackColor=panel2,Margin=new Padding(4)};Label l=new Label(){Text=caption,ForeColor=muted,Location=new Point(10,7),AutoSize=true};value=new Label(){Text="—",ForeColor=text,Font=new Font("Segoe UI Semibold",11,FontStyle.Bold),Location=new Point(10,30),Size=new Size(178,28),AutoEllipsis=true};p.Controls.Add(l);p.Controls.Add(value);parent.Controls.Add(p);}
    void Choose(string filter){using(OpenFileDialog d=new OpenFileDialog()){d.Filter=filter;d.Multiselect=false;if(d.ShowDialog(this)==DialogResult.OK)OpenPath(d.FileName);}}
    void OnDragEnter(object s,DragEventArgs e){if(e.Data.GetDataPresent(DataFormats.FileDrop))e.Effect=DragDropEffects.Copy;}
    void OnDragDrop(object s,DragEventArgs e){string[] f=(string[])e.Data.GetData(DataFormats.FileDrop);if(f.Length>0)OpenPath(f[0]);}
    public void OpenPath(string path){try{data=Parser.Read(path);fileLabel.Text=Path.GetFileName(path);molecule.Atoms=data.Atoms;molecule.ResetView();countLabel.Text=data.Atoms.Count+" atoms";raw.Text=data.Text;FillLists();if(voidUpdate!=null)voidUpdate();chart.Values=data.Energies;statusLabel.Text=data.Atoms.Count>0?data.Atoms.Count+" 个原子 · "+data.Kind.ToUpperInvariant()+" 已载入":data.Kind.ToUpperInvariant()+" 已载入；未识别到结构坐标";tabs.SelectedIndex=0;if(data.Kind=="inp"&&data.Atoms.Count==0&&data.Text.IndexOf("xyzfile",StringComparison.OrdinalIgnoreCase)>=0)MessageBox.Show(this,"该输入使用 xyzfile 引用外部结构。请再打开相应的 .xyz 文件查看结构。","ORCA View",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){MessageBox.Show(this,"无法读取文件：\r\n"+ex.Message,"ORCA View",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
    void FillLists(){atomList.Items.Clear();int i=0;foreach(Atom a in data.Atoms){i++;ListViewItem it=new ListViewItem(i.ToString(CultureInfo.InvariantCulture));it.SubItems.Add(a.E);it.SubItems.Add(a.X.ToString("0.0000",CultureInfo.InvariantCulture));it.SubItems.Add(a.Y.ToString("0.0000",CultureInfo.InvariantCulture));it.SubItems.Add(a.Z.ToString("0.0000",CultureInfo.InvariantCulture));atomList.Items.Add(it);}freqList.Items.Clear();for(i=0;i<data.Frequencies.Count;i++){double f=data.Frequencies[i];ListViewItem it=new ListViewItem((i+1).ToString());it.SubItems.Add(f.ToString("0.00",CultureInfo.InvariantCulture));it.SubItems.Add(f<0?"虚频":"");if(f<0)it.ForeColor=Color.FromArgb(255,133,140);freqList.Items.Add(it);}}
    void UpdateUI(Label nat,Label charge,Label method,Label energy,Label cycles,Label conv){nat.Text=data.Atoms.Count>0?data.Atoms.Count.ToString():"—";charge.Text=data.Charge.HasValue?data.Charge.Value+" / "+data.Multiplicity.Value:"—";method.Text=String.IsNullOrEmpty(data.Method)?"—":data.Method;energy.Text=data.Energy.HasValue?data.Energy.Value.ToString("0.00000000",CultureInfo.InvariantCulture):"—";cycles.Text=data.Cycles>0?data.Cycles.ToString():"—";conv.Text=data.Converged?"已收敛":(data.Cycles>0?"未确认":"—");conv.ForeColor=data.Converged?Color.LightGreen:text;}
    void SaveXYZ(){if(data.Atoms.Count==0){MessageBox.Show(this,"当前没有可导出的结构。","ORCA View");return;}using(SaveFileDialog d=new SaveFileDialog(){Filter="XYZ 结构 (*.xyz)|*.xyz",FileName=Path.GetFileNameWithoutExtension(data.FileName)+"_view.xyz"})if(d.ShowDialog(this)==DialogResult.OK){StringBuilder b=new StringBuilder();b.AppendLine(data.Atoms.Count.ToString());b.AppendLine("Exported by ORCA View");foreach(Atom a in data.Atoms)b.AppendLine(String.Format(CultureInfo.InvariantCulture,"{0,-3} {1,14:F8} {2,14:F8} {3,14:F8}",a.E,a.X,a.Y,a.Z));File.WriteAllText(d.FileName,b.ToString(),new UTF8Encoding(false));}}
  }

  static class Parser {
    static Regex coord=new Regex(@"^\s*([A-Z][a-z]?)\s+([-+]?\d*\.?\d+(?:[Ee][-+]?\d+)?)\s+([-+]?\d*\.?\d+(?:[Ee][-+]?\d+)?)\s+([-+]?\d*\.?\d+(?:[Ee][-+]?\d+)?)",RegexOptions.Compiled);
    static List<Atom> Rows(string s){List<Atom>a=new List<Atom>();foreach(string l in s.Split(new[]{"\r\n","\n"},StringSplitOptions.None)){Match m=coord.Match(l);if(m.Success){double x,y,z;if(Double.TryParse(m.Groups[2].Value,NumberStyles.Float,CultureInfo.InvariantCulture,out x)&&Double.TryParse(m.Groups[3].Value,NumberStyles.Float,CultureInfo.InvariantCulture,out y)&&Double.TryParse(m.Groups[4].Value,NumberStyles.Float,CultureInfo.InvariantCulture,out z))a.Add(new Atom(m.Groups[1].Value,x,y,z));}}return a;}
    public static ResultData Read(string path){string txt=File.ReadAllText(path,Encoding.UTF8);ResultData d=new ResultData();d.FileName=Path.GetFileName(path);d.Kind=Path.GetExtension(path).TrimStart('.').ToLowerInvariant();d.Text=txt;if(d.Kind=="inp")ParseInp(d);else if(d.Kind=="out"||d.Kind=="log")ParseOut(d);else if(d.Kind=="xyz")ParseXYZ(d);else if(d.Kind=="gjf"||d.Kind=="com")ParseGjf(d);else if(d.Kind=="cif")ParseCif(d);return d;}
    static void ParseInp(ResultData d){Match q=Regex.Match(d.Text,@"\*\s*xyz\s+(-?\d+)\s+(\d+)",RegexOptions.IgnoreCase);if(q.Success){d.Charge=Int32.Parse(q.Groups[1].Value);d.Multiplicity=Int32.Parse(q.Groups[2].Value);}Match b=Regex.Match(d.Text,@"\*\s*xyz\s+-?\d+\s+\d+\s*\r?\n([\s\S]*?)\r?\n\s*\*",RegexOptions.IgnoreCase);if(b.Success)d.Atoms=Rows(b.Groups[1].Value);Match meth=Regex.Match(d.Text,@"^\s*!\s*(.+)$",RegexOptions.Multiline);if(meth.Success)d.Method=meth.Groups[1].Value.Trim();}
    static void ParseOut(ResultData d){string[] lines=d.Text.Split(new[]{"\r\n","\n"},StringSplitOptions.None);List<Atom> last=null;for(int i=0;i<lines.Length;i++){if(lines[i].IndexOf("CARTESIAN COORDINATES (ANGSTROEM)",StringComparison.OrdinalIgnoreCase)<0)continue;int j=i+1;while(j<lines.Length&&(lines[j].Trim().Length==0||Regex.IsMatch(lines[j].Trim(),"^-+$")))j++;List<Atom> block=new List<Atom>();while(j<lines.Length){Match m=coord.Match(lines[j]);if(!m.Success){if(block.Count>0)break;j++;continue;}double x,y,z;if(Double.TryParse(m.Groups[2].Value,NumberStyles.Float,CultureInfo.InvariantCulture,out x)&&Double.TryParse(m.Groups[3].Value,NumberStyles.Float,CultureInfo.InvariantCulture,out y)&&Double.TryParse(m.Groups[4].Value,NumberStyles.Float,CultureInfo.InvariantCulture,out z))block.Add(new Atom(m.Groups[1].Value,x,y,z));j++;}if(block.Count>0)last=block;}if(last!=null)d.Atoms=last;
      foreach(Match m in Regex.Matches(d.Text,@"FINAL SINGLE POINT ENERGY\s+([-+]?\d+\.\d+)",RegexOptions.IgnoreCase)){double e;if(Double.TryParse(m.Groups[1].Value,NumberStyles.Float,CultureInfo.InvariantCulture,out e))d.Energies.Add(e);}if(d.Energies.Count>0)d.Energy=d.Energies[d.Energies.Count-1];foreach(Match m in Regex.Matches(d.Text,@"GEOMETRY OPTIMIZATION CYCLE\s+(\d+)",RegexOptions.IgnoreCase)){int n;if(Int32.TryParse(m.Groups[1].Value,out n))d.Cycles=Math.Max(d.Cycles,n);}d.Converged=Regex.IsMatch(d.Text,"THE OPTIMIZATION HAS CONVERGED",RegexOptions.IgnoreCase);foreach(Match m in Regex.Matches(d.Text,@"^\s*\d+\s*:\s*([-+]?\d+\.\d+)\s+cm\*\*-1",RegexOptions.Multiline)){double f;if(Double.TryParse(m.Groups[1].Value,NumberStyles.Float,CultureInfo.InvariantCulture,out f))d.Frequencies.Add(f);}foreach(string l in lines){if(Regex.IsMatch(l,@"\bWARNING\b",RegexOptions.IgnoreCase))d.Warnings.Add(l.Trim());if(Regex.IsMatch(l,@"error termination|\bERROR\b|aborting the run|not converged",RegexOptions.IgnoreCase))d.Errors.Add(l.Trim());}
      Match q=Regex.Match(d.Text,@"\*\s*xyz\s+(-?\d+)\s+(\d+)",RegexOptions.IgnoreCase);if(q.Success){d.Charge=Int32.Parse(q.Groups[1].Value);d.Multiplicity=Int32.Parse(q.Groups[2].Value);}Match meth=Regex.Match(d.Text,@"^\s*!\s*(.+)$",RegexOptions.Multiline);if(meth.Success)d.Method=meth.Groups[1].Value.Trim();}
    static void ParseXYZ(ResultData d){string[] l=d.Text.Split(new[]{"\r\n","\n"},StringSplitOptions.None);int n;if(l.Length<2||!Int32.TryParse(l[0].Trim(),out n))return;StringBuilder b=new StringBuilder();for(int i=2;i<Math.Min(l.Length,n+2);i++)b.AppendLine(l[i]);d.Atoms=Rows(b.ToString());}
    static void ParseGjf(ResultData d){string[] l=d.Text.Split(new[]{"\r\n","\n"},StringSplitOptions.None);int i=Array.FindIndex(l,x=>Regex.IsMatch(x,@"^\s*-?\d+\s+\d+\s*$"));if(i<0)return;string[] q=l[i].Trim().Split((char[])null,StringSplitOptions.RemoveEmptyEntries);int c,m;if(Int32.TryParse(q[0],out c)&&Int32.TryParse(q[1],out m)){d.Charge=c;d.Multiplicity=m;}StringBuilder b=new StringBuilder();for(i++;i<l.Length&&coord.IsMatch(l[i]);i++)b.AppendLine(l[i]);d.Atoms=Rows(b.ToString());}
    static void ParseCif(ResultData d){string[] ls=d.Text.Split(new[]{"\r\n","\n"},StringSplitOptions.None);double[] cell=new double[3];string[] ck={"_cell_length_a","_cell_length_b","_cell_length_c"};for(int k=0;k<3;k++){string s=ls.FirstOrDefault(x=>x.TrimStart().StartsWith(ck[k],StringComparison.OrdinalIgnoreCase));if(s!=null){string[] p=s.Trim().Split((char[])null,StringSplitOptions.RemoveEmptyEntries);Double.TryParse(p[p.Length-1],NumberStyles.Float,CultureInfo.InvariantCulture,out cell[k]);}}for(int i=0;i<ls.Length;i++){if(!ls[i].Trim().Equals("loop_",StringComparison.OrdinalIgnoreCase))continue;int j=i+1;List<string> h=new List<string>();while(j<ls.Length&&ls[j].TrimStart().StartsWith("_atom_site_",StringComparison.OrdinalIgnoreCase))h.Add(ls[j++].Trim());int el=h.FindIndex(x=>x.EndsWith("_type_symbol",StringComparison.OrdinalIgnoreCase));int ix=h.FindIndex(x=>x.EndsWith("_Cartn_x",StringComparison.OrdinalIgnoreCase)),iy=h.FindIndex(x=>x.EndsWith("_Cartn_y",StringComparison.OrdinalIgnoreCase)),iz=h.FindIndex(x=>x.EndsWith("_Cartn_z",StringComparison.OrdinalIgnoreCase));int fx=h.FindIndex(x=>x.EndsWith("_fract_x",StringComparison.OrdinalIgnoreCase)),fy=h.FindIndex(x=>x.EndsWith("_fract_y",StringComparison.OrdinalIgnoreCase)),fz=h.FindIndex(x=>x.EndsWith("_fract_z",StringComparison.OrdinalIgnoreCase));if(el<0)continue;for(;j<ls.Length;j++){string s=ls[j].Trim();if(s.Length==0||s.StartsWith("#"))break;string[] p=s.Split((char[])null,StringSplitOptions.RemoveEmptyEntries);if(p.Length<h.Count||el>=p.Length)break;double x,y,z;bool cart=ix>=0&&iy>=0&&iz>=0;int ax=cart?ix:fx,ay=cart?iy:fy,az=cart?iz:fz;if(ax<0||ay<0||az<0)break;if(!Double.TryParse(p[ax],NumberStyles.Float,CultureInfo.InvariantCulture,out x)||!Double.TryParse(p[ay],NumberStyles.Float,CultureInfo.InvariantCulture,out y)||!Double.TryParse(p[az],NumberStyles.Float,CultureInfo.InvariantCulture,out z))break;if(!cart){x*=cell[0];y*=cell[1];z*=cell[2];}string e=p[el];d.Atoms.Add(new Atom(e.Substring(0,1).ToUpperInvariant()+e.Substring(1).ToLowerInvariant(),x,y,z));}if(d.Atoms.Count>0)return;}}
  }

  class MoleculeCanvas : Panel {
    public List<Atom> Atoms=new List<Atom>(); public bool ShowBonds=true,ShowLabels=false; double rx=-.35,ry=.55,zoom=1,px=0,py=0; Point last; bool dragging,pan;
    Dictionary<string,double> rad=new Dictionary<string,double>(StringComparer.OrdinalIgnoreCase){{"H",.31},{"C",.76},{"N",.71},{"O",.66},{"F",.57},{"P",1.07},{"S",1.05},{"Cl",1.02},{"Br",1.20},{"I",1.39},{"Ag",1.45},{"Au",1.36},{"Cu",1.32},{"Pt",1.36},{"Pd",1.39},{"Fe",1.32},{"Co",1.26},{"Ni",1.24},{"Zn",1.22},{"Si",1.11},{"Na",1.66},{"Mg",1.41},{"Ca",1.76}};
    public MoleculeCanvas(){DoubleBuffered=true;SetStyle(ControlStyles.ResizeRedraw,true);MouseDown+=(s,e)=>{dragging=true;pan=e.Button==MouseButtons.Right||ModifierKeys.HasFlag(Keys.Shift);last=e.Location;Capture=true;};MouseMove+=(s,e)=>{if(!dragging)return;int dx=e.X-last.X,dy=e.Y-last.Y;if(pan){px+=dx;py+=dy;}else{ry+=dx*.008;rx=Math.Max(-1.5,Math.Min(1.5,rx+dy*.008));}last=e.Location;Invalidate();};MouseUp+=(s,e)=>{dragging=false;Capture=false;};MouseWheel+=(s,e)=>{zoom=Math.Max(.2,Math.Min(6,zoom*(e.Delta>0?1.12:.89)));Invalidate();};}
    public void ResetView(){zoom=1;px=py=0;Invalidate();}
    struct P { public double x,y,z; public float sx,sy,r; public Atom a; }
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);Graphics g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(BackColor);if(Atoms==null||Atoms.Count==0){using(Font f=new Font("Segoe UI",13))using(SolidBrush b=new SolidBrush(Color.FromArgb(148,157,174)))g.DrawString("打开 ORCA 输入、输出或结构文件\n\n拖动旋转  ·  滚轮缩放  ·  右键拖动平移",f,b,new RectangleF(25,Height/2-55,Width-50,120),new StringFormat(){Alignment=StringAlignment.Center});return;}
      double cx=Atoms.Average(a=>a.X),cy=Atoms.Average(a=>a.Y),cz=Atoms.Average(a=>a.Z),c=Math.Cos(ry),s=Math.Sin(ry),c2=Math.Cos(rx),s2=Math.Sin(rx);List<P> q=new List<P>();double minx=1e9,maxx=-1e9,miny=1e9,maxy=-1e9;foreach(Atom a in Atoms){double X=a.X-cx,Y=a.Y-cy,Z=a.Z-cz,u=X*c-Z*s,v=X*s*s2+Y*c2+Z*c*s2,w=X*s*c2-Y*s2+Z*c*c2;minx=Math.Min(minx,u);maxx=Math.Max(maxx,u);miny=Math.Min(miny,v);maxy=Math.Max(maxy,v);q.Add(new P{x=u,y=v,z=w,a=a});}double span=Math.Max(Math.Max(maxx-minx,maxy-miny),1),scale=Math.Min(Width,Height)*.76/span*zoom;double mx=(maxx+minx)/2,my=(maxy+miny)/2;for(int i=0;i<q.Count;i++){P p=q[i];p.sx=(float)(Width/2+(p.x-mx)*scale+px);p.sy=(float)(Height/2-(p.y-my)*scale+py);p.r=(float)Math.Max(3.3,Radius(p.a.E)*scale*.24);q[i]=p;}
      if(ShowBonds){using(Pen pen=new Pen(Color.FromArgb(135,149,169),1.8f)){for(int i=0;i<q.Count;i++)for(int j=i+1;j<q.Count;j++){P a=q[i],b=q[j];double dx=a.a.X-b.a.X,dy=a.a.Y-b.a.Y,dz=a.a.Z-b.a.Z,d2=dx*dx+dy*dy+dz*dz,lim=Radius(a.a.E)+Radius(b.a.E);if(d2>.35&&d2<lim*lim*1.18)g.DrawLine(pen,a.sx,a.sy,b.sx,b.sy);}}}
      foreach(P a in q.OrderBy(x=>x.z)){Color col=ElementColor(a.a.E);RectangleF r=new RectangleF(a.sx-a.r,a.sy-a.r,a.r*2,a.r*2);using(GraphicsPath path=new GraphicsPath()){path.AddEllipse(r);using(PathGradientBrush br=new PathGradientBrush(path)){br.CenterColor=ControlPaint.Light(col,0.78f);br.SurroundColors=new[]{ControlPaint.Dark(col,0.22f)};br.CenterPoint=new PointF(a.sx-a.r*.32f,a.sy-a.r*.35f);g.FillEllipse(br,r);}}if(ShowLabels&&a.r>5){using(Font f=new Font("Segoe UI",8,FontStyle.Bold))using(SolidBrush b=new SolidBrush(Color.White))g.DrawString(a.a.E,f,b,a.sx+3,a.sy-a.r-13);}}
    }
    double Radius(string e){double x;return rad.TryGetValue(e,out x)?x:1.2;} Color ElementColor(string e){switch(e){case "H":return Color.FromArgb(225,231,240);case "C":return Color.FromArgb(112,123,143);case "N":return Color.FromArgb(75,126,232);case "O":return Color.FromArgb(228,82,92);case "P":return Color.FromArgb(221,148,67);case "S":return Color.FromArgb(212,183,64);case "Ag":return Color.FromArgb(175,188,204);case "Au":return Color.FromArgb(220,179,67);case "Cu":return Color.FromArgb(196,116,72);case "Cl":return Color.FromArgb(63,176,96);case "Br":return Color.FromArgb(148,82,52);case "I":return Color.FromArgb(128,75,157);default:return Color.FromArgb(151,166,178);}}
  }
  class EnergyChart : Panel { public List<double> Values=new List<double>(); protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);Graphics g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(BackColor);int l=48,r=15,t=18,b=28;using(Pen grid=new Pen(Color.FromArgb(54,60,73)))using(SolidBrush brush=new SolidBrush(Color.FromArgb(148,157,174)))using(Font f=new Font("Segoe UI",8)){for(int i=0;i<4;i++){float y=t+i*(Height-t-b)/3f;g.DrawLine(grid,l,y,Width-r,y);}if(Values==null||Values.Count<2){g.DrawString(Values!=null&&Values.Count==1?"只有一个能量点":"等待载入优化能量",f,brush,l+8,Height/2);return;}double mn=Values.Min(),mx=Values.Max(),span=mx-mn;if(span==0)span=1;PointF[] pts=Values.Select((v,i)=>new PointF(l+i*(Width-l-r)/(float)(Values.Count-1),t+(float)((mx-v)/span)*(Height-t-b))).ToArray();using(Pen line=new Pen(Color.FromArgb(151,137,255),2.2f))g.DrawLines(line,pts);g.DrawString("循环 1",f,brush,4,Height-b+4);g.DrawString("循环 "+Values.Count,f,brush,Width-67,Height-b+4);g.DrawString(Values.Count+" 个能量点；纵轴相对能量",f,brush,l,t-12);}}
  }
